"""Provider-free safety and recovery contract for the ProtoCosmo2 canary.

This module deliberately performs no Telegram or model-provider I/O.  A future
transport adapter must feed Telegram updates into :class:`CanaryContract`,
deliver only its durable outbox records, and acknowledge delivery receipts.
All mutable state crosses an atomic filesystem seam, matching the Phase-5 file
bridges and avoiding network/socket ownership inside Janus/SWI.
"""
from __future__ import annotations

import hashlib
import json
import os
import tempfile
from dataclasses import dataclass
from pathlib import Path
from typing import Any, Mapping


SCHEMA_VERSION = 2
STATE_SCHEMA_VERSION = 2
EXPECTED_IDENTITY = "ProtoCosmo2"
MAX_ALLOWLIST_IDS = 16
MAX_RATE_LIMIT = 1_000
MAX_RATE_WINDOW_SECONDS = 86_400
MAX_REPLY_DEPTH_LIMIT = 8
MAX_TEXT_LIMIT = 4_096
MAX_INBOUND_TEXT_LIMIT = 65_536
MAX_PROCESSED_IDS = 2_048
MAX_CONTEXT_MESSAGES = 64
MAX_CONTEXT_CHARS = 120_000
FAILURE_TEXT = "ProtoCosmo2 could not complete this message safely. The failure was recorded for review."


class ConfigError(ValueError):
    """The canary configuration is malformed or unsafe."""


class StateError(RuntimeError):
    """Durable state is malformed or violates the transaction protocol."""


@dataclass(frozen=True)
class CanaryConfig:
    identity: str
    allowed_chat_ids: frozenset[int]
    allowed_user_ids: frozenset[int]
    allow_all_group_chats: bool
    allow_all_group_users: bool
    max_outbound_messages: int
    rate_window_seconds: int
    max_reply_depth: int
    max_text_chars: int


def _exact_int(value: Any, name: str, minimum: int, maximum: int) -> int:
    if type(value) is not int or not minimum <= value <= maximum:
        raise ConfigError(f"{name} must be an integer in {minimum}..{maximum}")
    return value


def _exact_bool(value: Any, name: str) -> bool:
    if type(value) is not bool:
        raise ConfigError(f"{name} must be boolean")
    return value


def _id_set(value: Any, name: str) -> frozenset[int]:
    if not isinstance(value, list) or not 1 <= len(value) <= MAX_ALLOWLIST_IDS:
        raise ConfigError(f"{name} must contain 1..{MAX_ALLOWLIST_IDS} ids")
    ids = frozenset(_exact_int(item, name, 1, 2**63 - 1) for item in value)
    if len(ids) != len(value):
        raise ConfigError(f"{name} must not contain duplicates")
    return ids


def _chat_id_set(value: Any) -> frozenset[int]:
    """Accept exact Telegram private/group chat IDs, but never zero or bool.

    Bot API supergroup/channel IDs are negative while user IDs are positive.
    Keeping the signed identifier intact is required for an explicit group
    allowlist; user IDs continue to use the positive-only ``_id_set``.
    """
    name = "allowed_chat_ids"
    if not isinstance(value, list) or not 1 <= len(value) <= MAX_ALLOWLIST_IDS:
        raise ConfigError(f"{name} must contain 1..{MAX_ALLOWLIST_IDS} ids")
    ids = frozenset(
        item for item in value
        if type(item) is int and item != 0 and -(2**63) <= item <= 2**63 - 1
    )
    if len(ids) != len(value):
        raise ConfigError(f"{name} must contain unique nonzero signed integers")
    return ids


def load_config(path: Path | str, *, expected_identity: str = EXPECTED_IDENTITY) -> CanaryConfig:
    """Load an exact, credential-free, fail-closed private-canary config."""
    try:
        raw = Path(path).read_bytes()
        if len(raw) > 16_384:
            raise ConfigError("config exceeds 16384 bytes")
        payload = json.loads(raw.decode("utf-8"))
    except ConfigError:
        raise
    except Exception as exc:
        raise ConfigError(f"cannot load config: {exc}") from exc
    required = {
        "schema_version", "identity", "allowed_chat_ids", "allowed_user_ids",
        "max_outbound_messages", "rate_window_seconds", "max_reply_depth",
        "max_text_chars", "attachments", "autonomous_schedules",
        "state_changing_extras", "allow_all_group_chats",
        "allow_all_group_users",
    }
    if not isinstance(payload, dict) or set(payload) != required:
        raise ConfigError("config must contain exactly the private-canary fields")
    if type(payload["schema_version"]) is not int or payload["schema_version"] != SCHEMA_VERSION:
        raise ConfigError("unsupported config schema_version")
    if (not isinstance(expected_identity, str) or not expected_identity
            or len(expected_identity) > 128):
        raise ConfigError("expected_identity is invalid")
    if payload["identity"] != expected_identity:
        raise ConfigError(f"identity must be {expected_identity!r}")
    if payload["attachments"] != "extract_text":
        raise ConfigError("attachments must use bounded text extraction")
    if payload["autonomous_schedules"] is not False:
        raise ConfigError("autonomous_schedules must be false")
    if payload["state_changing_extras"] is not False:
        raise ConfigError("state_changing_extras must be false")
    return CanaryConfig(
        identity=payload["identity"],
        allowed_chat_ids=_chat_id_set(payload["allowed_chat_ids"]),
        allowed_user_ids=_id_set(payload["allowed_user_ids"], "allowed_user_ids"),
        allow_all_group_chats=_exact_bool(payload["allow_all_group_chats"], "allow_all_group_chats"),
        allow_all_group_users=_exact_bool(payload["allow_all_group_users"], "allow_all_group_users"),
        max_outbound_messages=_exact_int(
            payload["max_outbound_messages"], "max_outbound_messages", 1, MAX_RATE_LIMIT
        ),
        rate_window_seconds=_exact_int(
            payload["rate_window_seconds"], "rate_window_seconds", 1, MAX_RATE_WINDOW_SECONDS
        ),
        max_reply_depth=_exact_int(payload["max_reply_depth"], "max_reply_depth", 0, MAX_REPLY_DEPTH_LIMIT),
        max_text_chars=_exact_int(payload["max_text_chars"], "max_text_chars", 1, MAX_TEXT_LIMIT),
    )


def _initial_state(identity: str) -> dict[str, Any]:
    return {
        "schema_version": STATE_SCHEMA_VERSION,
        "identity": identity,
        "next_update_offset": None,
        "processed_message_ids": [],
        "pending_inbound": None,
        "outbox": [],
        "outbound_reserved_at": [],
        "incident_sequence": 0,
        "recent_context": [],
    }


class CanaryContract:
    """Durable inbox/outbox transaction boundary for one private canary."""

    def __init__(self, config: CanaryConfig, state_directory: Path | str):
        self.config = config
        self.directory = Path(state_directory)
        self.directory.mkdir(mode=0o700, parents=True, exist_ok=True)
        self.state_path = self.directory / "state.json"
        self.incident_path = self.directory / "incidents.jsonl"
        if self.state_path.exists():
            self.state = self._load_state()
        else:
            self.state = _initial_state(config.identity)
            self._save_state()

    @property
    def failure_text(self) -> str:
        return (
            f"{self.config.identity} could not complete this message safely. "
            "The failure was recorded for review."
        )

    def _load_state(self) -> dict[str, Any]:
        try:
            state = json.loads(self.state_path.read_text(encoding="utf-8"))
        except Exception as exc:
            raise StateError(f"cannot load canary state: {exc}") from exc
        if isinstance(state, dict) and state.get("schema_version") == 1:
            state["schema_version"] = STATE_SCHEMA_VERSION
            state["recent_context"] = []
            self.state = state
            self._save_state()
        required = set(_initial_state(self.config.identity))
        if not isinstance(state, dict) or set(state) != required:
            raise StateError("canary state has an unexpected schema")
        if state["schema_version"] != STATE_SCHEMA_VERSION or state["identity"] != self.config.identity:
            raise StateError("canary state identity/schema mismatch")
        if not isinstance(state["processed_message_ids"], list) or not isinstance(state["outbox"], list):
            raise StateError("canary state list fields are malformed")
        if not isinstance(state["outbound_reserved_at"], list):
            raise StateError("canary rate state is malformed")
        if not isinstance(state["recent_context"], list):
            raise StateError("canary context state is malformed")
        return state

    def _save_state(self) -> None:
        data = (json.dumps(self.state, ensure_ascii=False, sort_keys=True, separators=(",", ":")) + "\n").encode()
        fd, temporary = tempfile.mkstemp(prefix="state.", suffix=".tmp", dir=self.directory)
        try:
            with os.fdopen(fd, "wb") as handle:
                handle.write(data)
                handle.flush()
                os.fsync(handle.fileno())
            os.replace(temporary, self.state_path)
            directory_fd = os.open(self.directory, os.O_RDONLY)
            try:
                os.fsync(directory_fd)
            finally:
                os.close(directory_fd)
        finally:
            try:
                os.unlink(temporary)
            except FileNotFoundError:
                pass

    def _incident(self, code: str, update_id: int | None, message_id: int | None, now: int) -> dict[str, Any]:
        self.state["incident_sequence"] += 1
        incident = {
            "sequence": self.state["incident_sequence"], "code": code,
            "update_id": update_id, "message_id": message_id, "observed_at": now,
        }
        with self.incident_path.open("a", encoding="utf-8") as handle:
            handle.write(json.dumps(incident, sort_keys=True, separators=(",", ":")) + "\n")
            handle.flush()
            os.fsync(handle.fileno())
        return incident

    @staticmethod
    def _inbound(update: Mapping[str, Any]) -> dict[str, Any]:
        required = {"update_id", "message_id", "chat_id", "user_id", "text", "reply_depth", "attachments"}
        if not isinstance(update, Mapping) or set(update) != required:
            raise ValueError("inbound update must contain exactly the contract fields")
        result = dict(update)
        for name in ("update_id", "message_id", "user_id", "reply_depth"):
            if type(result[name]) is not int or result[name] < (0 if name in {"update_id", "reply_depth"} else 1):
                raise ValueError(f"{name} is invalid")
        if type(result["chat_id"]) is not int or result["chat_id"] == 0:
            raise ValueError("chat_id is invalid")
        if (not isinstance(result["text"], str) or not result["text"]
                or len(result["text"]) > MAX_INBOUND_TEXT_LIMIT):
            raise ValueError("text is invalid")
        if not isinstance(result["attachments"], list) or len(result["attachments"]) > 16:
            raise ValueError("attachments is invalid")
        return result

    def _advance(self, inbound: Mapping[str, Any]) -> None:
        message_ids = self.state["processed_message_ids"]
        message_ids.append(f"{inbound['chat_id']}:{inbound['message_id']}")
        self.state["processed_message_ids"] = message_ids[-MAX_PROCESSED_IDS:]
        offset = inbound["update_id"] + 1
        current = self.state["next_update_offset"]
        self.state["next_update_offset"] = offset if current is None else max(current, offset)
        self.state["pending_inbound"] = None

    def skip_update(self, update_id: int) -> None:
        """Advance past a transport-filtered update without creating output."""
        if type(update_id) is not int or update_id < 0:
            raise ValueError("update_id is invalid")
        offset = update_id + 1
        current = self.state["next_update_offset"]
        self.state["next_update_offset"] = offset if current is None else max(current, offset)
        self._save_state()

    def observe_context(self, update: Mapping[str, Any]) -> None:
        """Persist bounded human group context without admitting work/output."""
        required = {"update_id", "message_id", "chat_id", "user_id", "text"}
        if not isinstance(update, Mapping) or set(update) != required:
            raise ValueError("context update fields are invalid")
        if any(type(update[name]) is not int for name in ("update_id", "message_id", "chat_id", "user_id")):
            raise ValueError("context identifiers are invalid")
        if update["update_id"] < 0 or update["message_id"] < 1 or update["chat_id"] >= 0 or update["user_id"] < 1:
            raise ValueError("context identifiers are out of range")
        text = update["text"]
        if not isinstance(text, str) or not text or len(text) > MAX_INBOUND_TEXT_LIMIT:
            raise ValueError("context text is invalid")
        records = self.state["recent_context"]
        records.append(dict(update))
        records = records[-MAX_CONTEXT_MESSAGES:]
        while records and sum(len(item["text"]) for item in records) > MAX_CONTEXT_CHARS:
            records.pop(0)
        self.state["recent_context"] = records
        self.skip_update(update["update_id"])

    def context_for_chat(self, chat_id: int, *, before_message_id: int, limit: int = 24) -> list[dict[str, Any]]:
        """Return bounded same-chat context preceding an addressed message."""
        if type(chat_id) is not int or chat_id >= 0 or type(before_message_id) is not int:
            raise ValueError("context query is invalid")
        matches = [
            dict(item) for item in self.state["recent_context"]
            if item["chat_id"] == chat_id and item["message_id"] < before_message_id
        ]
        return matches[-max(0, min(limit, 24)):]

    def abandon_pending(self, code: str, *, now: int) -> dict[str, Any]:
        """Close an operator-identified unsafe pending input without replying."""
        pending = self.state["pending_inbound"]
        if pending is None:
            return {"status": "clean"}
        incident = self._incident(code, pending["update_id"], pending["message_id"], now)
        self._advance(pending)
        self._save_state()
        return {"status": "abandoned", "incident": incident}

    def admit_inbound(self, update: Mapping[str, Any], *, now: int) -> dict[str, Any]:
        """Durably claim an update, reject it, or identify it as a duplicate."""
        try:
            inbound = self._inbound(update)
        except ValueError as exc:
            incident = self._incident("malformed_inbound", None, None, now)
            self._save_state()
            return {"status": "rejected", "reason": str(exc), "incident": incident}
        pending = self.state["pending_inbound"]
        message_key = f"{inbound['chat_id']}:{inbound['message_id']}"
        if message_key in self.state["processed_message_ids"]:
            return {"status": "duplicate", "message_id": inbound["message_id"]}
        offset = self.state["next_update_offset"]
        if offset is not None and inbound["update_id"] < offset:
            return {"status": "duplicate", "message_id": inbound["message_id"], "reason": "stale_update"}
        if pending is not None:
            if pending["message_id"] == inbound["message_id"]:
                return {"status": "recovery_required", "message_id": inbound["message_id"]}
            incident = self._incident("pending_inbound_blocks_new_update", inbound["update_id"], inbound["message_id"], now)
            self._save_state()
            return {"status": "blocked", "incident": incident}
        is_group = inbound["chat_id"] < 0
        chat_allowed = inbound["chat_id"] in self.config.allowed_chat_ids or (
            is_group and self.config.allow_all_group_chats
        )
        user_allowed = inbound["user_id"] in self.config.allowed_user_ids or (
            is_group and self.config.allow_all_group_users
        )
        if not chat_allowed or not user_allowed:
            incident = self._incident("allowlist_rejected", inbound["update_id"], inbound["message_id"], now)
            self._advance(inbound)
            self._save_state()


