    )
    addressed = not sender_is_bot and (
        chat_id >= 0 or bot_username.casefold() in text.casefold() or replied_to_bot
    )
    attachments = []
    for key in attachment_keys:
        if key in message:
            attachments.append({"kind": key, "value": message[key]})
    return {"update_id": update_id, "message_id": message_id, "chat_id": chat_id,
            "user_id": user_id, "text": text,
            "reply_depth": int(isinstance(reply, Mapping) and isinstance(reply.get("from"), Mapping)
                               and reply["from"].get("is_bot") is True),
            "attachments": attachments, "addressed": addressed,
            "sender_is_bot": sender_is_bot}


class PrivateCanaryTelegramTransport:
    def __init__(
        self, contract: CanaryContract, api: TelegramApi, responder: Callable[[str], str],
        *, bot_id: int = BOT_ID, bot_username: str = BOT_USERNAME,
        attachment_label: str = "ProtoCosmo2",
    ):
        self.contract, self.api, self.responder = contract, api, responder
        if type(bot_id) is not int or bot_id <= 0:
            raise ValueError("bot_id is invalid")
        if (not isinstance(bot_username, str) or not bot_username.startswith("@")
                or len(bot_username) > 65):
            raise ValueError("bot_username is invalid")
        if not isinstance(attachment_label, str) or not attachment_label or len(attachment_label) > 128:
            raise ValueError("attachment_label is invalid")
        self.bot_id = bot_id
        self.bot_username = bot_username
        self.attachment_label = attachment_label

    def _deliver_one(self, now: int) -> bool:
        queued = self.contract.next_outbound()
        if queued is None:
            return False
        attachments = queued["attachments"]
        if attachments:
            attachment = attachments[0]
            receipt = self.api.send_document(
                chat_id=queued["chat_id"], path=Path(attachment["path"]),
                filename=attachment["filename"], mime_type=attachment["mime_type"],
                caption=queued["text"], reply_to_message_id=queued["reply_to_message_id"],
            )
        else:
            receipt = self.api.send_message(chat_id=queued["chat_id"], text=queued["text"],
                                            reply_to_message_id=queued["reply_to_message_id"])
        self.contract.mark_delivered(queued["outbox_id"], receipt, now=now)
        return True

    def _attachment_reply(self, answer: str) -> tuple[str, list[dict[str, str]]]:
        """Accept one explicit, workspace-confined ``MEDIA:`` attachment directive.

        The directive is intentionally recognised only as the first non-empty
        line, so quoted or explanatory ``MEDIA:`` text cannot exfiltrate a
        file.  The outbox records a resolved regular file under the research
        workspace, making restart delivery deterministic and bounded.
        """
        # The MeTTa ``send`` boundary can return the model's whole reply as a
        # JSON-style quoted string (including escaped newlines).  Unwrap only
        # that exact scalar form before looking for the directive.  The normal
        # path and all path/type/root checks below remain unchanged.
        candidate = answer
        stripped = answer.strip()
        if stripped.startswith('"') and stripped.endswith('"'):
            try:
                unwrapped = json.loads(stripped)
            except json.JSONDecodeError:
                pass
            else:
                if isinstance(unwrapped, str):
                    candidate = unwrapped
        if candidate.lstrip().startswith("MEDIA:"):
            candidate = candidate.replace("\\n", "\n")
        lines = candidate.splitlines()
        first = next((index for index, line in enumerate(lines) if line.strip()), None)
        if first is None or not lines[first].lstrip().startswith("MEDIA:"):
            return answer, []
        raw_path = lines[first].lstrip()[len("MEDIA:"):].strip().strip("`")
        if not raw_path or "\x00" in raw_path:
            raise ValueError("invalid MEDIA path")
        path = Path(raw_path)
        if not path.is_absolute() or path.is_symlink():
            raise ValueError("MEDIA path must be an absolute non-symlink")
        resolved = path.resolve(strict=True)
        if OUTBOUND_ROOT not in resolved.parents or not resolved.is_file():
            raise ValueError("MEDIA path is outside the approved workspace")
        if resolved.stat().st_size > MAX_OUTBOUND_DOCUMENT_BYTES:
            raise ValueError("MEDIA document exceeds 50 MB")
        mime_type = OUTBOUND_DOCUMENT_TYPES.get(resolved.suffix.casefold())
        if mime_type is None:
            raise ValueError("MEDIA document must be PDF or LaTeX")
        caption = "\n".join(lines[first + 1:]).strip() or f"{self.attachment_label} attachment: {resolved.name}"
        if len(caption) > 1024:
            raise ValueError("MEDIA caption exceeds Telegram's 1024-character limit")
        return caption, [{"path": str(resolved), "filename": resolved.name, "mime_type": mime_type}]

    def _extract_attachment_text(self, inbound: dict[str, Any]) -> dict[str, Any]:
        attachments = inbound["attachments"]
        if not attachments:
            return inbound
        if len(attachments) != 1 or attachments[0].get("kind") != "document":
            return inbound
        value = attachments[0].get("value")
        if not isinstance(value, Mapping):
            return inbound
        try:
            extracted = self.api.extract_document(value)
        except Exception:
            return inbound
        if not isinstance(extracted, str) or not extracted.strip():
            return inbound
        inbound = dict(inbound)
        inbound["text"] = (
            inbound["text"]
            + "\n\n<external_untrusted_document>\n"
            + extracted.strip()
            + "\n</external_untrusted_document>"
        )
        inbound["attachments"] = []
        return inbound

    def _prompt_with_context(self, inbound: dict[str, Any]) -> str:
        if inbound["chat_id"] >= 0:
            return inbound["text"]
        history = self.contract.context_for_chat(
            inbound["chat_id"], before_message_id=inbound["message_id"]
        )
        if not history:
            return inbound["text"]
        lines = [
            f"[message_id={item['message_id']} user_id={item['user_id']}] {item['text']}"
            for item in history
        ]
        return (
            "<external_untrusted_telegram_group_context>\n"
            + "\n".join(lines)
            + "\n</external_untrusted_telegram_group_context>\n\n"
            + inbound["text"]
        )

    def start_from_now(self) -> int:
        if self.contract.next_update_offset not in (None, 0):
            return self.contract.next_update_offset
        # Telegram's negative offset asks for the newest queued update and
        # forgets earlier history.  This is a stronger fresh-start fence than
        # an unbounded snapshot, which may transiently return an empty list.
        updates = self.api.get_updates(-1, 0)
        maximum = max((item.get("update_id", -1) for item in updates if type(item.get("update_id")) is int), default=-1)
        if self.contract.next_update_offset is None:
            self.contract.initialize_offset(maximum + 1)
        else:
            self.contract.rebase_pristine_offset(maximum + 1)
        return maximum + 1

    def recover_startup(self, *, now: int | None = None) -> dict[str, Any]:
        """Close an interrupted transaction before polling for new work.

        The contract deliberately never reruns a prompt whose execution may
        have begun before a crash.  Recovery instead preserves an existing
        outbox record or queues its fixed visible-failure reply; the next poll
        then delivers that durable item exactly once.
        """
        return self.contract.recover_after_crash(now=int(time.time()) if now is None else now)

    def run_once(self, *, poll_timeout: int = 15, now: int | None = None) -> dict[str, int]:
        current = int(time.time()) if now is None else now
        sent, accepted, rejected, duplicates = int(self._deliver_one(current)), 0, 0, 0
        for raw in self.api.get_updates(self.contract.next_update_offset, poll_timeout):
            inbound = _safe_update(raw, bot_id=self.bot_id, bot_username=self.bot_username)
            if inbound is None:
                update_id = raw.get("update_id") if isinstance(raw, Mapping) else None
                if type(update_id) is int and update_id >= 0:
                    self.contract.skip_update(update_id)
                continue
            inbound = self._extract_attachment_text(inbound)
            addressed = inbound.pop("addressed")
            sender_is_bot = inbound.pop("sender_is_bot")
            if sender_is_bot and inbound["chat_id"] >= 0:
                self.contract.skip_update(inbound["update_id"])
                continue
            if inbound["chat_id"] < 0 and not addressed:
                self.contract.observe_context({
                    key: inbound[key]
                    for key in ("update_id", "message_id", "chat_id", "user_id", "text")
                })
                continue
            result = self.contract.admit_inbound(inbound, now=current)
            if result["status"] in {"duplicate", "recovery_required"}:
                duplicates += 1
                continue
            if result["status"] != "accepted":
                rejected += 1
                sent += int(self._deliver_one(current))
                continue
            accepted += 1
            try:
                prompt = self._prompt_with_context(inbound)
                answer = self.responder(prompt)
                caption, attachments = self._attachment_reply(answer)
                self.contract.queue_reply(caption, reply_depth=inbound["reply_depth"] + 1,
                                          now=current, attachments=attachments)
            except Exception:
                self.contract.fail_inbound("responder_failure", now=current)
            sent += int(self._deliver_one(current))
            break
        return {"accepted": accepted, "rejected": rejected, "duplicates": duplicates, "sent": sent}


