#!/usr/bin/env bash
set -euo pipefail

ROOT=/home/openclaw/research-agent/projects/omegaclaw
RUNNER="$ROOT/protocosmo2/tools/phase6_private_canary_runner.py"
CORE="$ROOT/repos/PeTTa/repos/OmegaClaw-Core"
TRANSPORT_CORE="$ROOT/worktrees/protocosmo2-phase6-live"
PETTA="$ROOT/repos/PeTTa"
DRIVER="$ROOT/protocosmo2/tools/phase5_omegaclaw_case.py"
ENV_FILE=/home/openclaw/.openclaw/omegaclaw-telegram.env
CONFIG=/home/openclaw/.openclaw/protomega-outer.json
STATE_DIR=/home/openclaw/.openclaw/protomega-outer-state
WORKER_STATE_DIR="$ROOT/local/protomega-worker-state"
PID_FILE="$ROOT/local/run-state/protomega-outer-telegram.pid"
LOG="$ROOT/artifacts/telegram-private-supervisor/protomega-outer-telegram.log"

alive() {
  [[ -f "$PID_FILE" ]] && kill -0 "$(cat "$PID_FILE")" 2>/dev/null
}

case "${1:-status}" in
  run)
    printf '%s\n' "$$" >"$PID_FILE"
    child_pid=""
    terminate() {
      if [[ -n "$child_pid" ]]; then
        kill -TERM "$child_pid" 2>/dev/null || true
        wait "$child_pid" 2>/dev/null || true
      fi
      if [[ "$(cat "$PID_FILE" 2>/dev/null || true)" == "$$" ]]; then rm -f "$PID_FILE"; fi
      exit 0
    }
    trap terminate TERM INT
    while true; do
      python3 "$RUNNER" \
        --env "$ENV_FILE" --config "$CONFIG" --state-dir "$STATE_DIR" \
        --worker-state-dir "$WORKER_STATE_DIR" --core "$CORE" \
        --transport-core "$TRANSPORT_CORE" --petta "$PETTA" --driver "$DRIVER" \
        --identity ProtomegaTron --bot-id 8562797306 --bot-username @Protomegabot \
        --session-prefix protomegatron-live --model openclaw/protomegabot-opus \
        --provider-timeout 300 --poll-timeout 15 </dev/null >>"$LOG" 2>&1 &
      child_pid=$!
      wait "$child_pid" || true
      child_pid=""
      sleep 5
    done
    ;;
  start)
    if alive; then echo "active pid $(cat "$PID_FILE")"; exit 0; fi
    [[ -f "$ENV_FILE" && -f "$CONFIG" ]]
    mkdir -p "$(dirname "$PID_FILE")" "$(dirname "$LOG")"
    rm -f "$PID_FILE"
    setsid -f "$0" run </dev/null >>"$LOG" 2>&1
    for _ in $(seq 1 20); do alive && break; sleep 0.25; done
    alive
    echo "started pid $(cat "$PID_FILE")"
    ;;
  stop)
    if alive; then kill -TERM "$(cat "$PID_FILE")"; fi
    rm -f "$PID_FILE"
    echo stopped
    ;;
  status)
    if alive; then echo "active pid $(cat "$PID_FILE")"; else echo inactive; exit 1; fi
    ;;
  *) echo "usage: $0 {start|stop|status|run}" >&2; exit 2 ;;
esac


